const outlineData = {"chapters":[{"chapterNumber":0,"title":"Preface","sections":[{"level":1,"heading":"Preface","bibleReferences":[],"subsections":[]}]},{"chapterNumber":1,"title":"Chapter 1: Biblical Theology and Systematic Theology in Covenant Theology","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Covenant theology (CT) explains God's single, unified redemptive purpose across all history","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Studying it requires humility (God's ways are unsearchable) balanced with diligence","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Four methodological challenges will structure the rest of the chapter","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. Scope and Simplicity","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: CT's scope is the whole of Scripture, worked at both the macro and micro levels","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Breadth of coverage","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Spans the whole of Scripture, from creation to consummation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Works at both the macro (big-picture) and micro (fine-detail) levels","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. What that breadth requires of the interpreter","bibleReferences":[],"subsections":[{"level":5,"heading":"1. CT must explain the theological weight of redemptive history, not just narrate it","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Large-scale conclusions must rest on thoroughly examined details, not shortcuts","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Conclusion \u2014 what that breadth rules out","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Oversimplified summaries that lose the connecting threads between parts","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Treating the \u201cbig picture\u201d as sufficient without the smaller supporting lines","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. Creation, Covenant, and Consequences","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: covenants are additions on top of nature, not part of it","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The basic distinction","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Creation and its natural order are built into the world by nature","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Covenants are additions on top of nature, not part of it","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. What follows for the Creator-creature relationship","bibleReferences":[],"subsections":[{"level":5,"heading":"1. By nature, creatures owe God obedience; God owes them nothing extra in return","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Covenants exist only because God freely grants benefits beyond what nature requires","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Two parallel distinctions this generates","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Natural law (known by nature) vs. positive law (added by revelation)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Natural worship (owed by nature) vs. instituted worship (regulated only by God's command)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iv. Consequence \u2014 the resulting limit on inference","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Because covenants aren't natural, no covenant's details can be assumed to carry over to another by logical necessity","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. A feature in one covenant (a seal, a blood ritual, family inclusion) doesn't automatically transfer to a different covenant","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Conclusion \u2014 what this does not mean","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It doesn't prevent comparing Scripture with Scripture on the same covenant","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. It doesn't require the word \u201ccovenant\u201d to appear explicitly for a covenant to be present","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"3. The Law and the Gospel","bibleReferences":[],"subsections":[{"level":3,"heading":"a. First sense \u2014 the doctrinal sense","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Law and gospel are opposite paths to righteousness \u2014 one earned by works, one received by faith","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. This contrast anchored the Reformation's break from Rome's blending of faith and works","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second sense \u2014 the historical sense","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Law and gospel also serve as broad labels for the Old and New Testament eras","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Revelation grows clearer over time, but the underlying way of salvation doesn't change","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 holding both senses together","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Old and New Testament believers were saved the same way, by grace through faith","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. That underlying continuity is not evidence that the Abrahamic, Mosaic, and Davidic covenants are simply identical to the New Covenant of grace","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. A sound CT preserves both the continuity in salvation and the real differences between the covenants themselves","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. History and Mystery","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion \u2014 what \u201cmystery\u201d means for Paul","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The full inclusion of the nations through Christ was revealed gradually and partially, not concealed forever","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. It reaches full clarity only through Christ's death, resurrection, and Pentecost","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Proof \u2014 evidence that it stayed partially hidden","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Even the disciples still expected a restored Jewish kingdom after the resurrection","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Full comprehension came only with a greater outpouring of the Spirit","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 what this requires of CT's method","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The Old Testament's witness to Christ must be allowed to stay veiled the way Scripture itself presents it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. New Testament clarity should not be read backward into earlier stages of revelation, since that would erase the very mystery Scripture describes","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The four considerations \u2014 scope, creation/covenant, law/gospel, mystery \u2014 form the necessary starting framework for the rest of the study","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Given the size and difficulty of the subject, the fitting response is humility and worship, not confidence in having mastered it","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":2,"title":"Chapter 2: Typology","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Typology is a core interpretive tool for reading Scripture in general and for covenant theology in particular","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. The Bible\u2019s covenants and its typological patterns are closely bound together \u2014 tracing one usually means tracing the other","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. What is Typology?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Basic definition","bibleReferences":[],"subsections":[{"level":4,"heading":"i. A divinely intended correspondence between an earlier person, event, or institution and a later, greater fulfillment","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Different theologians phrase this differently, but generally agree on the core idea","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Core features of a type (following Beale\u2019s definition)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Analogical correspondence \u2014 a real likeness between the type and its fulfillment","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Historicity \u2014 the type is a real historical person, event, or institution, not a literary device","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. A pointing-forward function, understood clearly only in hindsight (\u201cretrospection\u201d)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Escalation \u2014 the fulfillment surpasses the type","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: a real heightening or intensification occurs","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: it is not a mere repetition of the same thing at the same level","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. How later Scripture unpacks earlier Scripture","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Old Testament passages carry a genuine but incomplete meaning at the time they were written","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the human authors truly understood what they wrote","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: their understanding was not exhaustive","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Later revelation, especially the New Testament, unfolds and expands that meaning without contradicting it","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Where types can be found","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Not limited to places where Scripture explicitly uses the word \u201ctype\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Interpreters may identify further typological connections, provided they stay anchored in Scripture\u2019s own pattern of usage rather than in speculation","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. What keeps this from becoming arbitrary","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Types are divinely ordained and preordained in advance, not simply noticed after the fact","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Christ must be the center of any legitimate typological reading","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: a type must ultimately point to Christ, His covenant, and His kingdom","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: a \u201ctype\u201d without Christ in view is not functioning as typology at all","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. The Relation between a Type and its Antitype","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Theologians often agree on typology\u2019s definition in the abstract but disagree sharply once they start applying it","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. This section works out the relationship more precisely","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Types reveal something greater, and other, than themselves.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Typology is not a sliding scale from a duller version to a brighter version of the same thing","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Scripture consistently uses paired contrasting language","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Shadow vs. substance","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Picture vs. reality","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Supporting examples show the type is not itself the fulfillment","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The wilderness bread (John 6:32\u201333, 58)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it pointed to Christ, the \u201ctrue bread from heaven\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: it was not itself a lesser version of Christ","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. The wilderness rock (1 Corinthians 10:4)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it portrayed Christ","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: the rock and its water were not actually Christ","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. The Mosaic law (Colossians 2:17)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it looked forward to Christ and His kingdom","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: it was not, in itself, Christ and His kingdom","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iv. The tabernacle and its sacrifices (Hebrews 8:5; 9:23\u201324; 10:1)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: they served as a copy and shadow of heavenly realities","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: the copies could not themselves purify what the true heavenly sacrifice would purify","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"b. Types function on two levels.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. The immediate level","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Types had a genuine function and meaning in their own original setting","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Example: animal sacrifices really addressed outward, ceremonial guilt under the Old Covenant","bibleReferences":[],"subsections":[{"level":6,"heading":"1. They dealt with purification of the flesh","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. But could not purify the conscience","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. The pointing-forward level","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The same institution simultaneously anticipated a greater, future fulfillment in Christ","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. This double function let Old Testament believers receive real benefit even from something that was not the final reality","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Contrast \u2014 why this differs from ordinary \u201calready/not yet\u201d language","bibleReferences":[],"subsections":[{"level":5,"heading":"i. New Testament blessings are the same reality experienced partially now and fully later","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Old Testament types worked differently","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: they signified one thing on the surface (an earthly meaning)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: while revealing something else entirely (a greater, heavenly meaning)","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"c. Types terminate in their antitypes.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: once the greater reality has come, the type that anticipated it is no longer needed","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Consequence: continuing to rely on the type after the fulfillment has arrived effectively denies that the fulfillment actually happened","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Illustrations offered","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Seeing a friend\u2019s shadow around a corner: you don\u2019t talk to the shadow once the friend himself appears","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A restaurant menu: once the food has arrived, the picture in the menu is no longer needed","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Types are positive and negative.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Some types anticipate the fulfillment by resemblance \u2014 a positive picture of what is to come","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Others anticipate it by highlighting their own failure or insufficiency \u2014 a negative contrast with what is to come","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Example: the yearly sacrifices served as a reminder of ongoing guilt (Hebrews 10:3) even while pointing toward a final, lasting remission of sins","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: either way, the comparison serves the same purpose \u2014 to magnify how much greater the fulfillment is than the type that anticipated it","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Application of Typological Principles","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Where theologians agreed","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Reformed theologians broadly agreed the Mosaic covenant had a typical, shadow-like character","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Where they disagreed","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Whether that typical character meant the Old and New Covenants differ merely in degree (an immature form growing into a mature form of the same covenant)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Or whether they differ in actual substance (genuinely different covenants, not just different stages)","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The two positions summarized","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Burgess\u2019s view","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the difference between the covenants is one of degree \u2014 from inferior to superior, from less to more","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: not a difference in substance","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Owen\u2019s view (and the Particular Baptists\u2019)","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the Old and New Covenants differ \u201cas to the essence and substance of them\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: not merely as different administrations of the very same covenant","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Conclusion \u2014 why this dispute matters","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Since a type is genuinely distinct from its antitype, treating the difference as one of \u201csubstance\u201d fits the nature of typology more consistently","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. This is the position followed in this book, aligning with Owen and the Particular Baptists rather than those who saw only a difference of degree","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Small differences in how typology gets applied can lead to very different theological systems down the line","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Getting the underlying principles right is therefore essential before drawing larger conclusions","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":3,"title":"Chapter 3: Covenant and Kingdom","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Two foundational questions need answers before going further: what is a covenant, and what does a covenant do?","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. What is a Covenant?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: a covenant involves binding commitments between two parties, secured by threats that guarantee they'll be kept","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Clarification: since God always initiates","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Positive: His covenants are gracious gifts","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Negative: not negotiated deals","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"a. The definition of a covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. The core shape","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Two parties make mutual \u201cI will / you will\u201d commitments","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Different kinds of commitments produce different kinds of covenants","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Why a commitment alone isn't enough","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A bare commitment lacks legal force until sanctions are attached","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Sanctions add the formality that turns a promise into a covenant","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion \u2014 why covenants are gracious, not negotiated","bibleReferences":[],"subsections":[{"level":5,"heading":"i. God imposes the terms; man doesn't get to bargain them","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Even so, every covenant offers real benefits beyond what nature already provides","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. Covenant sanctions","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: covenant-making in the Ancient Near East and in Scripture consistently involves dramatic ritual sanctions","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof \u2014 the pattern","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Animals cut in half","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Oaths invoking curses","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Proof \u2014 examples across Scripture","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Jeremiah 34 (the covenant to free Jewish slaves, later broken)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Psalm 50 (\u201cmade a covenant with me by sacrifice\u201d)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Jonathan and David in 1 Samuel 20 (a self-directed curse without a blood ritual)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"4. Abraham in Genesis 15 (God takes the death-oath upon Himself)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Second assertion: a close reading of Hebrews 9:16\u201317 confirms this same sanction-based logic, against the standard translation","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Problem with the ESV's translation","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The ESV reads it as a last will and testament","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Renihan argues this is inadequate and proposes a covenant-ratification reading instead","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Exegetical step 1 \u2014 why \u201ccovenant,\u201d not \u201ctestament,\u201d is the right frame","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Old Testament usage of \u03b4\u03b9\u03b1\u03b8\u03ae\u03ba\u03b7 (covenant) always describes an arrangement between living parties","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: covenants are struck between the living","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: not wills activated only at death","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"2. It would be foreign to biblical usage for the concept of a will to suddenly appear in Hebrews without warning","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. Exegetical step 2 \u2014 what must the covenanter do (\u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The Greek verb in question is \u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. The ESV treats it as meaning \u201cto be established,\u201d i.e., death is brought forward as evidence","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Renihan argues it must be read alongside a related word used elsewhere in Hebrews, \u03c0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03c9, which refers to priestly offerings","bibleReferences":[],"subsections":[]},{"level":6,"heading":"4. Drawing the contrast","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: the covenanter's death is \u201cbrought forward as evidence\u201d or \u201cpledged\u201d (\u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9) \u2014 an oath guaranteeing future participation","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: the covenanter is not himself being sacrificed or offered up (\u03c0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03c9)","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"5. The idea is that a potential death is sworn as security, not that an actual death has occurred","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iv. Exegetical step 3 \u2014 the prepositional phrase \u1f10\u03c0\u1f76 \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2 (\u201cat death\u201d)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The word \u03bd\u03b5\u03ba\u03c1\u03cc\u03c2 refers to the state of being dead, not the event of dying","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: Hebrews 9:16 uses \u03b8\u03ac\u03bd\u03b1\u03c4\u03bf\u03c2 for the event of dying","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: verse 17 shifts to \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2, which does not carry that meaning","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"2. \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2 is plural (\u201cdead bodies\u201d), not singular","bibleReferences":[],"subsections":[{"level":7,"heading":"A will only requires one body to take effect","bibleReferences":[],"subsections":[]},{"level":7,"heading":"A covenant is consistently associated with multiple bodies or corpses at its inauguration (citing O. Palmer Robertson)","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"3. Conclusion of this step: the phrase should be rendered \u201cby corpses\u201d or \u201cover corpses,\u201d not \u201cat death\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"v. Exegetical step 4 \u2014 confirmation from Psalm 50:5 in Greek","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The Greek text says covenants (\u03b4\u03b9\u03b1\u03b8\u03ae\u03ba\u03b7) are made \u201cby sacrifice\u201d (\u1f10\u03c0\u1f76 \u03b8\u03c5\u03c3\u03af\u03b1\u03b9\u03c2)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. This mirrors the same construction used in Hebrews 9:17","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. The parallel supports reading Hebrews as describing covenant ratification by sacrifice","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"vi. Exegetical step 5 \u2014 completing the translation (\u03b2\u03b5\u03b2\u03b1\u03af\u03b1 vs. \u1f30\u03c3\u03c7\u03cd\u03b5\u03b9)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. \u03b2\u03b5\u03b2\u03b1\u03af\u03b1 = \u201cformally established, ratified, valid\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. \u1f30\u03c3\u03c7\u03cd\u03b5\u03b9 = \u201cto be in force, to be strong\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. The logic: a covenant is ratified by corpses precisely so that it will not be in force while the covenanter is alive and could violate it","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: the threat of death secures the covenant's terms","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: without that threat, the covenant would have no power or force","bibleReferences":[],"subsections":[]}]}]},{"level":5,"heading":"vii. Illustration","bibleReferences":[],"subsections":[{"level":6,"heading":"1. A parking lot with posted fines for disabled spaces is respected; one without posted fines is not","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Summary: \u201cno sanctions, no covenant\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"viii. Conclusion of this exegetical argument","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The precise form of covenant-making ceremonies varies across Scripture","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. But in every case, some sanction guarantees that the covenantal commitments will be fulfilled","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Without imprecatory oaths or threats, a covenant carries no binding force","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"c. The matter and form of a covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Definition \u2014 the two categories","bibleReferences":[],"subsections":[{"level":5,"heading":"i. \u201cMatter\u201d = the actual content of the commitments","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Law, or","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Promise","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. \u201cForm\u201d = the point at which sanctions formally ratify those commitments","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Application \u2014 how this produces two kinds of covenants","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A covenant built on law and obedience becomes a covenant of works","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A covenant built on promise and reception becomes a covenant of grace","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Qualification","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Not every covenant is a pure either/or case","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Some biblical covenants (like the ones with Israel) combine promise and obedience for different purposes within the same covenant","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Federal headship","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion \u2014 the basic principle","bibleReferences":[],"subsections":[{"level":5,"heading":"i. God consistently deals with groups of people through one representative head \u2014 Adam, Noah, Abraham, David, Christ","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Proof \u2014 why headship is \u201cimmediate\u201d","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Descendants are connected to the head directly, regardless of how many generations separate them","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Supporting examples","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The wilderness generation's children still inherited Canaan through Abraham, not through their disobedient parents","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Levi is said to have tithed to Melchizedek \u201cin Abraham's loins\u201d (Hebrews 7:9\u201310)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Conclusion \u2014 what this means for covenant membership","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Belonging to a covenant is determined by relationship to its federal head, not simply by family lineage as such","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Parents can be the means by which a child enters a covenant, but the head \u2014 not the parents \u2014 is what actually grounds that membership","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. What is a Covenant's Function?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion \u2014 the basic function","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Covenants are the legal means by which God delegates and structures rule over a kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. They define a kingdom's boundaries, leaders, laws, and promises","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Application \u2014 the three kingdoms this book traces","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The kingdom of creation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. The kingdom of Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. The kingdom of Christ","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 how they relate to each other","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Each kingdom is governed by its own set of covenants","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. All three converge in the one final kingdom of God under Christ","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. A covenant is a divinely guaranteed commitment that defines a relationship with God","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. It functions as the legal foundation on which God establishes and governs a kingdom \u2014 the framework the rest of the book will trace from creation onward","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":4,"title":"Chapter 4: The Covenant of Works","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Objection: opponents point out that Genesis 1\u20133 never uses the word \u201ccovenant\u201d for God\u2019s dealings with Adam","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Response: examining what God actually did with Adam beyond his mere status as a creature reveals a genuine covenantal transaction, whether or not the word itself appears","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. Man\u2019s Created Condition","bibleReferences":["Genesis 1:31"],"subsections":[{"level":3,"heading":"a. Assertion: creation, and man within it, was good","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof: Genesis 1 declares this good seven times, summed up in \u201cexceedingly good\u201d (Genesis 1:31)","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Man\u2019s natural goodness sets the stage for what God offers beyond that natural condition","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Positive: by nature, Adam owed complete obedience to God as Creator","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Negative: by nature, God was not obligated to reward that obedience with anything beyond the approval of justice","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Comparison: Genesis 1 and Genesis 2 give complementary perspectives","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Genesis 1 = the macro/universal view \u2014 dominion over all the earth, filling and subduing it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Genesis 2 = the local/micro view \u2014 the specific conditions under which that universal task begins","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion: Genesis 1 sets the scope of the coming covenant; Genesis 2 fills in the details","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. Man\u2019s Covenantal Condition","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Definition: a covenant = a commitment plus divine sanctions","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. God placed Adam under obligations beyond his created status, added sanctions to guarantee them, and committed to a reward \u2014 this sanctioned arrangement is the Covenant of Works","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. God placed Adam in the garden of Eden","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Genesis 2:8 \u2014 Eden was prepared and Adam was placed there","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: Eden was a specially prepared location","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it was not Adam\u2019s original or natural starting place","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Assertion: Eden functioned as a temple, a sanctuary of God\u2019s special presence","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Its features echo temple imagery: eastern orientation, elevated/mountaintop location, precious stones, and trees","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Comparison: later biblical temples are described using language that draws on Eden\u2019s imagery, suggesting Eden is the prototype","bibleReferences":[],"subsections":[{"level":7,"heading":"God\u2019s presence is repeatedly manifested on mountaintops (Sinai, the Jerusalem temple, Mount Zion in Hebrews 12:22)","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The precious stones anticipate the tabernacle/temple\u2019s construction and Aaron\u2019s breastplate, and align with Revelation\u2019s gemstone imagery","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The trees anticipate the almond-tree-shaped Menorah (Exodus 25:31\u201339) and the tree of life named again in Revelation 22","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"3. Throughout redemptive history, God consistently refuses to allow sin into His holy spaces","bibleReferences":[],"subsections":[{"level":7,"heading":"Adam is banished from Eden after the fall","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The tabernacle, temple, and the land of Israel itself were kept pure, with expulsion threatened for violation","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The individual believer is called a temple of the Holy Spirit, and the church must guard its membership boundaries","bibleReferences":[],"subsections":[]}]}]}]},{"level":4,"heading":"c. Conclusion: God made Eden a sanctuary and placed Adam there as its worker","bibleReferences":[],"subsections":[{"level":5,"heading":"i. By placing Adam there as worker, God granted him a specific realm to rule \u2014 Eden was Adam\u2019s kingdom, and he was its king","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. God appointed Adam federal head over his natural offspring","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Adam was federal head over mankind by God\u2019s own appointment","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Romans 5:19 \u2014 Adam\u2019s one trespass brought condemnation on those he represented","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. 1 Corinthians 15:22 \u2014 \u201cin Adam all die\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. 1 Corinthians 15:47\u201349 \u2014 humanity bears the image of \u201cthe man of dust\u201d","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Principle: as goes the king, so goes the kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Objection/complication: Genesis 1:28\u2019s commission to fill the earth is given in the plural, to both Adam and Eve together","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Response","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The universal scope of Genesis 1 must be read together with its local recapitulation in Genesis 2, where Adam alone is created, placed in the garden, and given his commission before Eve exists","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Eve\u2019s creation serves to help Adam carry out his commission \u2014 the command runs through Adam first, with Eve as his helper","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Conclusion: Adam is constituted federal head over his natural offspring; all mankind (Christ excepted, by virgin birth) is represented in him","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. God obligated Adam to a law of obedience","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First point: the basis of the law","bibleReferences":[],"subsections":[{"level":5,"heading":"i. By nature, Adam owed absolute obedience to God (the natural/moral law)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Beyond that, God added a positive law \u2014 commands arising purely from His revealed will","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Definition: the combination of natural law and this added positive command constitutes the Covenant of Works, named for the fact that obedience is its governing principle","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second assertion: Adam\u2019s task of \u201cworking\u201d and \u201ckeeping\u201d the garden (Genesis 2:15) was a priestly duty","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The same Hebrew verbs are used in Numbers 3:6\u201310 to describe the Levites guarding the tabernacle","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. That passage warns that \u201cif any outsider comes near, he shall be put to death\u201d \u2014 the same principle applies to Adam\u2019s guarding of Eden","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Application: the general command to guard the sanctuary is made specific in Genesis 2:16\u201317 \u2014 free to eat any tree except the tree of the knowledge of good and evil, on pain of death","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Extension: Adam\u2019s role also carries a prophetic dimension","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Receiving God\u2019s word directly is itself a mark of prophetic commission (compare Moses relaying Levitical commands in Numbers 3:5\u20136)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A prophet must not only receive God\u2019s word but also relay it purely and resist any challenge to it \u2014 Adam was responsible to guard against any threat to God\u2019s word in Eden","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Sequence and significance","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The priestly/prophetic commission is given to Adam first, then Eve is created as helper, then the universal commands of multiplication and dominion are given to both","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Two related aspects highlighted by this sequence","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Adam\u2019s role is kingly \u2014 bringing creation to consummation by filling the earth with a holy, God-honoring seed","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Adam\u2019s universal rule is determined by his local rule \u2014 whether Eden\u2019s boundaries expand to the whole earth depends entirely on his obedience regarding the one forbidden tree","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"e. Conclusion \u2014 summary","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works combines the moral law with an added positive command","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Adam, as priest, prophet, and king of Eden, was to begin universal dominion by first succeeding in one specific, local test","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. God promised eternal life to Adam","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: the tree of life symbolized the promised reward of eternal life","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A bare law is not a covenant \u2014 Adam\u2019s obedience functioned within a covenant that suspended a promised reward on that obedience","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The tree of life represented the goal set before him","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: if Adam obeyed, the tree of life stood as a pledge of confirmed eternal life","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: confirmed eternal life and unbreakable communion with God were not part of Adam\u2019s natural constitution \u2014 he was sinless and upright, but still able to sin","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. 1 John 3:4 defines sin as lawlessness; Adam was capable of violating God\u2019s law, and did","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Proof from later Scripture","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Revelation 2:7 \u2014 the tree of life\u2019s benefits are promised to the one who perseveres in trusting Christ","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Revelation 22 \u2014 the tree of life appears again at the consummation, equated with eternal life","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Genesis 3:22\u201324 \u2014 Adam\u2019s expulsion is specifically tied to being barred from the tree of life","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Second assertion: Paul\u2019s Adam-Christ comparisons confirm what Adam\u2019s obedience would have earned","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Argument from Romans 5: had Adam obeyed, the result would have paralleled Christ\u2019s obedience \u2014 righteousness for all he represented; Adam was the pattern for Christ\u2019s mission, not the reverse","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Argument from Romans 3:23: the \u201cglory\u201d Adam fell short of because of sin was a glory he could have attained through obedience in this covenant, a glory Christ has now entered and brings \u201cmany sons\u201d into (Hebrews 2:10)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Third assertion: no mercy was built into this covenant \u2014 Adam had to obey perfectly, personally, and perpetually","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. What it cost Christ to earn eternal life for His people","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. The severity with which the covenant\u2019s curse fell after the very first breach","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. The pattern of God\u2019s own Sabbath rest adds a future orientation \u2014 Adam was to bring about a kingdom and then enter rest, just as God did at creation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. The reward\u2019s dependence on the covenant is what makes it meritorious at all \u2014 apart from God\u2019s arrangement, Adam\u2019s obedience would have earned nothing","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Confirmed eternal life in righteousness was genuinely offered to Adam, and because such a reward could only come through God\u2019s free condescension, this constitutes a real covenant","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. If Adam had obeyed: the reward would belong to him and all he represented; Eden would extend to the whole earth; creation would reach consummation with no distinction between heaven and earth","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"e. God threatened Adam with sanctions","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Sanctions are what formalize covenantal commitments","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Assertion: God clearly threatened Adam with death for disobedience (Genesis 2:17)","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: there was no allowance for mercy, no room for partial fulfillment, no admission of failure","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Consequence: if Adam broke God\u2019s rule, he would surely die, his commission would end in ruin, and the seed he was meant to bring to glory would fall with him","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Symbol: the tree of the knowledge of good and evil functioned as the sacramental symbol of this threat, paired against the tree of life as the symbol of the promise","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: its ongoing presence served as a constant reminder of the necessity of obedience and the cost of unfaithfulness","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"f. God made a Covenant of Works with Adam","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: taken together, God\u2019s dealings with Adam beyond his natural condition constitute a genuine Covenant of Works","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Summary of the evidence: a defined kingdom, a federal head, a law of obedience, a promised reward, and a threatened curse \u2014 all present, even without the explicit word \u201ccovenant\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof: Nehemiah Coxe argued that God dealt with Adam \u201cnot only upon Terms of a Law, but in a way of Covenant,\u201d and that where the thing itself is sufficiently revealed, there is no need to insist on exact terminology","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Objection considered seriously \u2014 why this matters","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Denying this foundational doctrine undermines the heart of salvation itself","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof/consequence (Coxe): only on the basis of such a covenant could Adam\u2019s posterity be involved in his standing or falling \u2014 deny the covenant, and that involvement becomes unaccountable","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. If Adam\u2019s federal headship is denied: there is no way for mankind to have fallen in him, no clear reason for the incarnation, no clear basis for God\u2019s wrath or humanity\u2019s spiritual deadness, and no framework for the imputation central to Romans 5","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Caution against a purely negative reading","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The covenant threatens death, but it is only ominous because Adam failed \u2014 God\u2019s covenants are always designed for man\u2019s good","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof (Coxe): as to its terms, this was a covenant of works; as to its relational privilege, a covenant of friendship; as to its reward, a covenant of rich bounty and goodness \u2014 though it included no pardoning mercy","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: the Covenant of Works was a supreme privilege and blessing; underestimating that truth leads to underestimating the depth of Adam\u2019s failure","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"g. God tested Adam\u2019s obedience","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First point: the nature of the test","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works was not an open-ended demand \u2014 it had a definite goal, requiring a definable probationary test","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The \u201ctripwire\u201d of that test was the positive command regarding the tree of the knowledge of good and evil","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Adam\u2019s universal commission depended entirely on this one local command","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second point: the failure itself","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Comparison: just as Jesus was later tempted in the wilderness, Adam was tempted in the garden","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Adam was called to keep the sanctuary pure and uphold God\u2019s word","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Eve was deceived by the serpent","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Adam listened to his wife rather than exercising his commissioned dominion","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. As a result, he failed to obey, the covenant\u2019s sanctions were fully activated, and his sin was imputed to all his posterity","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Proof of what was at stake: Romans 3:23 and 5:17\u201318 indicate that had Adam obeyed, he would have attained God\u2019s glory and constituted \u201cthe many\u201d as righteous","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Illustration (Meredith Kline): Adam\u2019s probation is described as a kind of judicial combat, requiring one decisive act of righteousness akin to a victory in battle against Satan \u2014 a victory that, had it been won, would have been imputed to all whom Adam represented","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: Adam failed this test, and mankind died in him \u2014 setting up the transition to humanity\u2019s cursed condition","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. Man\u2019s Cursed Condition","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Problem: God said Adam would \u201csurely die\u201d the day he ate the fruit, yet Adam did not die physically that day \u2014 does this mean the curse wasn\u2019t actually activated?","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Resolution: no \u2014 the curse was poured out in full; death, in multiple senses, descended on Adam that very day","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Death","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: because Adam was federal head, his curse fell on all of mankind collectively","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Romans 5:12 \u2014 sin and death spread to all because all sinned in Adam","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. 1 Corinthians 15:21\u201322 \u2014 \u201cin Adam all die\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Consequence: this is collective, imputed death \u2014 mankind\u2019s legal record is Adam\u2019s record","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second point: physical death","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Not instant, but certain \u2014 disease, weakness, and eventual death await all","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. 1 Corinthians 15 \u2014 bearing \u201cthe image of the man of dust,\u201d humanity returns to dust","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Third point: spiritual death \u2014 man\u2019s immaterial part is already dead, even before the body dies","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: Ephesians 2:1\u20133 \u2014 \u201cdead in trespasses and sins,\u201d \u201cchildren of wrath\u201d by nature","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: man\u2019s mind still knows God exists (Romans 1)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Negative: man suppresses that knowledge in unrighteousness and exchanges the truth for a lie","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Further proof: Ephesians 4:18 (mind darkened), 1 Corinthians 2:14 (the natural man cannot discern spiritual things)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"v. Fallen man\u2019s rejection of truth is both passive (it \u201cjust happens\u201d) and active (he suppresses, distorts, and disbelieves)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"vi. Consequence: man cannot choose or do spiritual good","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: man retains the power of choice and remains a free agent","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: that will is not free from a nature bent toward sin, and cannot choose or accomplish spiritual good","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Qualification: man is capable of civic or outwardly good acts, but nothing that pleases God or satisfies His law (Matthew 7:17\u201318; Romans 5:6; 8:7\u20138; Titus 3:3)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"d. Fourth point: eternal death \u2014 the most severe dimension","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Matthew 25 and Revelation 20 describe a final division between everlasting life and everlasting punishment","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. This is the direct opposite of the eternal life Adam would have secured through obedience, reinforced by his being barred specifically from the tree of life (Genesis 3:22)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Conclusion: the cursed condition involves death in every sense, culminating in permanent exclusion from God\u2019s glory","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The abrogation of the covenant of works","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: the covenant remains \u201cin force\u201d today in the sense that its curse still applies to all Adam\u2019s offspring","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it does not remain in force in the sense of still offering life for obedience to its commands","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Proof \u2014 why this is so","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works depended on positive laws tied to Eden specifically; with no more Eden or sacramental trees, there are no more such commands to obey","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The covenant was made with Adam as federal head, not with each individual descendant directly","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion of this point: the promise of the Covenant of Works is permanently closed off","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Illustration: returning to the path of the Covenant of Works after the fall leads not to heaven but back to a cursed, guarded Eden \u2014 the way is blocked not only by human inability but by God\u2019s active barring of it","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Second point \u2014 the moral law\u2019s continued authority","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Qualification: the abrogation of the covenant\u2019s positive laws does not touch the ongoing authority of the moral law","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof (Coxe): \u201cThe Law of Creation binds when the Covenant of Creation is broken\u201d \u2014 retained as a \u201crule of life\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. This obligation carries no promise attached, since the duty to obey belongs to the Creator-creature relationship by nature, while reward does not","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Third point \u2014 effect on the mandate to work and multiply","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The obligation to work and multiply remains, but the curse changes its character","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. First, human work can never secure more than a somewhat longer or easier life","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Second, the specific curses on man and woman directly hinder those mandates \u2014 painful childbearing for the woman, resistant ground for the man","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"f. Conclusion: the Covenant of Works is abrogated as to its promises and positive laws, but its moral demands and curses continue to bind and condemn","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. A merciful curse","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God did not immediately impose the full severity of the curse \u2014 an act of mercy","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Proof: before pronouncing curses on Adam and Eve, God first curses the serpent (Genesis 3:15), and that curse on Satan contains a promise of salvation for mankind","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Adam and Eve were hopeless in themselves at that moment, yet God speaks of deliverance before announcing their own curses","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Genesis 3:15 promises enmity between the serpent and the woman\u2019s offspring, and that offspring\u2019s eventual victory","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Contrast: by following Satan, Adam and Eve had aligned themselves with him as king; yet Satan\u2019s own curse places him lowest of all, pictured by the snake\u2019s position in the dust","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Significance of the sequence: because Eve\u2019s offspring is promised before Adam and Eve\u2019s own curses are pronounced, their punishment becomes chastisement rather than pure condemnation \u2014 discipline from a father, not a verdict from a judge","bibleReferences":[],"subsections":[]},{"level":4,"heading":"g. They are not immediately freed from the Covenant of Works\u2019 lesser curses, but they are freed from its ultimate curse of eternal death; their hope now rests in a coming descendant","bibleReferences":[],"subsections":[]},{"level":4,"heading":"h. Clarification on what this promise is not","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: it is not a new command for self-improvement or self-deliverance, and not a law paired with a threat","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: it is a promise God Himself must fulfill, to be simply received and believed","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"i. Conclusion: this moment marks the earliest dawning of the mystery of Christ, His covenant, and His kingdom","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. The Protological Nature of the Kingdom","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Definition: \u201cprotology\u201d refers to the foundational symbols and patterns that God establishes early on and repeats throughout the rest of Scripture","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Eden and the Covenant of Works function as this foundational pattern \u2014 the movement from protology to eschatology is another way of describing the movement from type to antitype","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Comparison","bibleReferences":[],"subsections":[{"level":4,"heading":"i. In Eden, a son of God is commissioned to bring the whole cosmos to a consummated, sinless kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Israel is later portrayed as a new son of God in a new paradise, under a new covenant, with its own temple, righteousness requirements, and promises of life","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Christ, the true and eternal Son of God, receives an everlasting covenant granting life in an eternal kingdom, again marked by temple, righteousness, and promised life","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Through the Covenant of Works, God delegated dominion over Eden to Adam, making him king of that realm","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. God established his federal headship, gave him a law of obedience, promised him a reward, and threatened him with a curse \u2014 all through this one covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. The covenant\u2019s purpose was to bring creation to consummation, extending Eden until the whole cosmos became God\u2019s dwelling","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Because Adam broke this covenant, creation as a whole remains under its government and its curse","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Yet God promised deliverance from that curse \u2014 and the rest of the book traces the unfolding of that promise","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":5,"title":"Chapter 5: The Noahic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The Covenant of Works has all of creation in view, and so does the Noahic Covenant \u2014 another covenant governing the kingdom of creation and its members, mankind","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Context: as man multiplied, so did his sinfulness, to the point that it seemed believers might be nearly wiped out","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. It is in that context that God sends the flood as judgment on mankind","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. A New Creation and Commission","bibleReferences":["Genesis 8:21","Genesis 9:1\u20132"],"subsections":[{"level":3,"heading":"a. First assertion: the flood narrative is deliberately composed to echo the Genesis 1 creation account","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Ruach/wind and the great deep reappear","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Dry land emerges from the waters again","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Birds again fill the heavens, and man and animals fill the earth","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. Noah, like Adam, receives a commission to be fruitful and fill the earth","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Qualification \u2014 what this parallel does NOT mean","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: it does not mean man returns to paradise or receives a new one","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: it does not mean man returns to innocence or obtains a new righteousness","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Proof: Genesis 8:21 \u2014 \u201cthe intention of man\u2019s heart is evil from his youth\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Consequence","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The flood saved the lives of Noah and his family","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. But it did not save their souls, and did not change the heart of man","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Positive: the face of the earth may be less full of wickedness","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. Negative: the heart of man remains just as corrupt as before","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Conclusion: the world Noah enters is not Eden, not paradise, and not a sacred place of God\u2019s presence \u2014 it is simply the fallen world","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second assertion: the commission given to Noah also echoes Eden, but differs sharply from Adam\u2019s","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Comparison","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Genesis 1\u2019s commission to Adam and Eve carried a positive tone \u2014 building, mastery, usefulness, cooperation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Genesis 9\u2019s commission to Noah achieves mastery over creation through fear and dread rather than wisdom and excellence","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Parallel: the same kind of \u201cfear and dread\u201d language later describes how the Canaanite nations will regard Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Application: Noah and mankind are called to build, cultivate, and establish human civilization, making use of the natural world","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Principle: this is a cultural mandate that functions as part of a covenant ruling a kingdom, and it applies equally to all mankind","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Consequence: everyone today is accountable to this covenant, since federal headship reaches every generation while the covenant remains active","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Application: all mankind \u2014 men and women \u2014 are called to build structured, successful societies","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: not called to idleness or despair","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: called to work, despite the resistance and difficulty the curse introduced","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"vii. Contrast with Adam\u2019s original task","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Adam and Eve were called to extend Eden and make the whole world a temple, gradually producing a holy, consummated paradise","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Noah\u2019s task differs sharply","bibleReferences":[],"subsections":[{"level":6,"heading":"(a) Present-day cultural achievement, however enjoyable by common grace, does not build the consummated kingdom of God","bibleReferences":[],"subsections":[]},{"level":6,"heading":"(b) It does not make the world a temple","bibleReferences":[],"subsections":[]},{"level":6,"heading":"(c) It does not fill the earth with a holy seed","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"viii. Conclusion: even faithful obedience to this commission does not advance a holy land, culture, or family in the way Adam\u2019s commission would have","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Third assertion: the Noahic Covenant is therefore not a covenant of salvation or eternal life","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof/consequence: success or failure in keeping its commission brings neither eternal life nor eternal death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Reason: mankind is already condemned in Adam, and at this point the only known escape was God\u2019s promise that Eve\u2019s offspring would crush the serpent\u2019s head","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Qualification: though it offers no eternal life itself, the Noahic Covenant still serves that greater promise of salvation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. How: its renewed commission to reproduce and expand provides the means by which the promised seed of Eve can eventually be born","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Historical logic: mankind\u2019s evil had grown so extreme that it threatened to wipe out the godly line entirely, so the Lord judged humanity through the flood in order to preserve His promise, and human multiplication can now resume serving that purpose","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Conclusion: this is Noah\u2019s \u2014 and mankind\u2019s \u2014 new commission","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. A Judicial Retribution","bibleReferences":["Genesis 9:5\u20137"],"subsections":[{"level":3,"heading":"a. First assertion: God establishes and governs His kingdoms through covenant; in the Noahic Covenant, He both renews the cultural mandate and establishes universal laws of justice, binding on every society","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text: Genesis 9:5\u20137 \u2014 God will require a reckoning for human bloodshed; whoever sheds man\u2019s blood, by man his blood shall be shed, because man bears God\u2019s image","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Application: this command binds all mankind, everywhere","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Principle: man\u2019s ongoing commission is still to be fruitful and multiply (repeated in v. 7)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Problem: murder directly works against that commission","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Resolution: to restrain mankind\u2019s sinfulness and prevent extreme bloodshed, murderers are made subject to death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Consequence: this establishes a genuine system of legal and judicial retribution within society","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vii. Explanation: this authority to punish wrongdoing is real power, derived from God Himself through this covenant","bibleReferences":[],"subsections":[]},{"level":4,"heading":"viii. Dual character of the death penalty","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It functions as an act of God\u2019s judgment on the murderer","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. It functions as an act of deliverance for the society itself","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. Second assertion: the Noahic Covenant gives human societies two basic, related responsibilities","bibleReferences":[],"subsections":[{"level":4,"heading":"i. To preserve life","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. To preserve the family","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Reasoning: since mankind is to be fruitful and multiply, and multiplication happens through families, society\u2019s core task is to promote and protect both","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Consequence: any society or government that corrupts the family, or murders the innocent, stands in direct treason against God","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It misuses the very authority \u2014 \u201cthe sword\u201d \u2014 entrusted to it, turning it on the innocent instead of the guilty","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Application to a contemporary example","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Assertion: government-sponsored, legally protected abortion is a stark instance of this violation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Reasoning: nothing opposes mankind\u2019s basic commission to be fruitful and multiply more directly than killing one\u2019s own children and shielding that killing by law","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Parallel example: the promotion of abortion alongside the erosion of marriage (widespread divorce, same-sex unions, sexual immorality) together constitute a rejection of the most basic duties the Noahic Covenant establishes","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Conclusion: the Noahic Covenant functions as a more fundamental constitution than any nation\u2019s own founding documents","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Application: society is obligated to","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Promote, preserve, and protect the life of individuals","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Promote, preserve, and protect the life of the family","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Consequence: this requires punishing the wicked, executing murderers, and cultivating genuinely loving, thriving families","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. A Promised Preservation","bibleReferences":["Genesis 9:8\u201317","Genesis 8:22"],"subsections":[{"level":3,"heading":"a. First assertion: covenants can be summarized as \u201cI will\u201d/\u201cyou will\u201d statements; having laid out man\u2019s obligations, God now makes His own commitment (Genesis 9:8\u201317)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text summary: God establishes His covenant with Noah, his offspring, and every living creature, promising the flood waters will never again destroy all flesh, with the rainbow given as the covenant\u2019s sign","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Scope of the promise, steadily expanding","bibleReferences":[],"subsections":[{"level":5,"heading":"1. From Noah","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. To his family","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. To all mankind","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. To all the earth","bibleReferences":[],"subsections":[]},{"level":5,"heading":"5. To all flesh","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Promise: the earth will never again be destroyed by a global flood","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Sacrament: the rainbow is given as a visible sign and promise of this reality","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second assertion: God further promises a stable natural order (Genesis 8:22 \u2014 seasons, cold and heat, day and night will continue predictably)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Qualification: this promise holds regardless of human obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Contrast: though this covenant does carry obligations, its promised blessings themselves are not withdrawn for disobedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion: God will not flood the earth again, and the rainbow stands as His visible pledge of that to the world","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Third point \u2014 clarifying the scope of this preservation","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Application: the sun shines on the righteous and the wicked alike","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Clarification on the scope of preservation","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: the promise is not one of eternal, unending preservation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: it is specifically that a flood will never again destroy the earth","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Clarification: this promise is not conditioned on human obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Qualification: God may still judge particular peoples or nations for their wickedness, but the whole of mankind will not suffer a repeat of universal judgment by flood","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Purpose and conclusion of this section","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Purpose: this promise creates a stable platform on which God\u2019s larger plan of salvation can play out","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Explanation: the mystery of Christ unfolds within this theater of preservation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Consequence: God\u2019s people, whether before or after Christ\u2019s coming, can know that the earth will endure until every one of God\u2019s promises has been fulfilled","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Conclusion: this covenant offers real comfort \u2014 however unstable the world seems, God\u2019s promises will still be kept","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. A Common Cursed Kingdom of Common Grace","bibleReferences":[],"subsections":[{"level":3,"heading":"a. First assertion (thesis): combining these elements shows that the kingdom of creation is best described as a common, cursed kingdom sustained by common grace","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Proof: the scope of Adam\u2019s and Noah\u2019s covenants is identical \u2014 both have the whole world in view","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Adam began in Eden, but his commission was to extend Eden to the whole world, and he served as federal head of all mankind","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: in Adam\u2019s fall, all sinned; all creation is governed by the Covenant of Works","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Proof: when Adam broke that covenant, all creation was cursed, both mankind and the ground itself","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Conclusion: God established the kingdom of creation through the Covenant of Works, and creation remains under its judgment and curse","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Noah\u2019s case: the flood narrative and his commission are framed as a new creation and new commission, echoing Adam\u2019s situation rather than repeating it exactly","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Parallel: just as Adam\u2019s covenant encompassed all mankind and creation, so does Noah\u2019s","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Conclusion: the kingdom of creation is governed by two covenants together","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Covenant of Works curses mankind","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. The Noahic Covenant stabilizes that cursed world so redemptive history can unfold and God\u2019s promises can be fulfilled","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Clarification: the Noahic Covenant and the Covenant of Works are not in tension \u2014 they simply serve different purposes","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Contrast: the Covenant of Works curses and condemns; the Noahic Covenant governs how to live within that cursed world","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Both remain active covenants through which God governs mankind and grants human authority","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Note: Adam forfeited his own authority, but in Noah, all people are still called to build culture and be fruitful and multiply","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Second assertion: this kingdom of creation is the common kingdom in which all mankind and all human societies live today","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Its curses apply to everyone; its promises and blessings apply to everyone","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Clarification: this kingdom does not itself offer salvation or saving grace","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Positive: it is nonetheless a genuine kindness from God that He gives rain and sunshine to all mankind in common, rather than curse and death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Conclusion: this is properly called the realm of common grace \u2014 God preserves the whole world, and the unbeliever has just as much claim to this common kindness as the believer, since both are citizens of the same common, cursed kingdom of common grace","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. Illustration: Ecclesiastes describes this as life \u201cunder the sun\u201d","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The system often doesn\u2019t work as it should \u2014 hard work doesn\u2019t always pay off, and laziness sometimes does","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Yet everyone is cursed, and everyone eventually dies","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion (drawn from Ecclesiastes): humanity\u2019s basic obligation in this common kingdom is simply to fear God and keep His commandments \u2014 to trust and obey, and nothing more","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Covenant and kingdom together give a clear, biblical way of understanding the world we live in","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. We inhabit the kingdom of creation \u2014 a common, cursed kingdom of common grace \u2014 established and governed jointly by the Covenant of Works and the Noahic Covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Comparison: this kingdom is marked for eventual destruction under the Covenant of Works (compared to Bunyan\u2019s \u201cCity of Destruction\u201d)","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Yet it is also granted preservation under the Noahic Covenant, for the sake of fulfilling all of God\u2019s promises","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Conclusion: all mankind, believer and unbeliever alike, benefits from that preserving kindness and common grace","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":6,"title":"Chapter 6: The Abrahamic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Before this covenant, there was no formally constituted nation of Israel, no defined people of God, and no specific land set apart for them","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Conclusion: all of that begins with God's covenant with Abraham","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Initiation of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Genesis 12:1\u20137 records the beginning of this covenant, and three elements within it deserve attention","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The federal head","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Principle: God consistently transacts His covenants through a federal head (as with Adam in the Covenant of Works, and Noah in the Noahic Covenant)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Assertion: God made this covenant with Abraham as federal head over his natural posterity","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: Genesis 12:2, 3, 7 \u2014 God promises Abraham a great nation and land for his offspring","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: participation in these promises depends on being encompassed by Abraham's federal headship, following the principle that as goes the king, so goes the kingdom","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The inheritance of Canaan","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God promised in verse 7 that Abraham and his descendants would inherit Canaan by right","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: this is not just the beginning of a covenant but the beginning of a kingdom granted through covenant \u2014 the beginning of the kingdom of Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Proof: before this, there was no Israel and no land peculiarly belonging to a people in covenant with God","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Conclusion: this covenant constituted Abraham and his descendants a kingdom-people by promising them the land of Canaan","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The blessing for the nations","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the Israelite kingdom and its covenants are preparatory and subservient to God's final purposes (Ephesians 1:10; 3:8\u201312)","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: the foundational promise of a universal blessing flowing through Abraham's descendants, now tied to a specific place on the map","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Explanation: the mystery of Christ will unfold in this place, among this people \u2014 Israel is the matrix of the mystery of Christ","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Qualification \u2014 this promise must be treated carefully","bibleReferences":[],"subsections":[{"level":5,"heading":"i. It is first a promise of connection by birth, a fleshly genealogical connection","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: this covenant provides a descendant who will bring the blessing","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Negative: it does not provide a relationship to that descendant beyond common genealogy \u2014 enjoying the blessing depends on one's relationship to the descendant, not to Abraham as such","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Assertion: from the beginning, this promise of blessing carried a transnational mindset, even as it established one nation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Conclusion","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Israel should never have taken pride in its national identity in a way that eclipsed or subverted this transnational purpose","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The nation exists to bring forth the Messiah \u2014 the Old Covenant exists to give birth to the New Covenant, the kingdom of Israel to give birth to the kingdom of Christ","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. The Confirmation of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: the covenant initiated through promises in Genesis 12 is formally confirmed in Genesis 15 through an official covenant-making ceremony","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Principle: a promise alone is not yet a covenant; sanctions are what formalize and finalize it","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Text: Genesis 15 repeats the promises of multiplied offspring and the land (vv. 5, 7), summarized in verse 18 \u2014 \u201cOn that day the LORD made a covenant with Abram\u201d","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Problem: Abraham, still childless, asks for confirmation beyond the bare promise (\u201chow am I to know that I shall possess it?\u201d)","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Resolution \u2014 the covenant-making ceremony","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Abraham is commanded to divide several animals and lay their halves opposite each other","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. God puts Abraham into a deep sleep, and in a vision a smoking fire pot and flaming torch pass between the pieces","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Exegetical significance: drawing on the earlier discussion of covenant sanctions, this is God swearing a self-maledictory oath \u2014 \u201cmay the same be done to Me and more also if I fail to keep My promise\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Conclusion: God sanctioned His commitment to Abraham, formally making it a covenant \u2014 He will multiply Abraham's offspring and give them the land of Canaan","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. Note: Genesis 12 and 15 together constitute a complete covenant, but the Abrahamic Covenant is not yet finished \u2014 Genesis 17 will expand it further","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"3. The Expansion of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. There is important continuity of promises across Genesis 12, 15, and 17 \u2014 the land promise is repeated each time","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Genesis 17 expands the covenant by adding a promise of royalty and a demand of loyalty","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. First addition: the promise of royalty","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text: Genesis 17:6 (\u201ckings shall come from you\u201d), repeated to Sarah in v. 16, and repeated again to Jacob in Genesis 35:11","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Narrowing: as Jacob's sons branch into tribes, the promise of royalty is narrowed specifically to Judah (Genesis 49:8\u201310)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion: this develops the kingdom of Israel from a general promise to Abraham into a specific promise concentrated in one tribe","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Second addition: the demand of loyalty (circumcision)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text: Genesis 17:9 \u2014 \u201cyou shall keep my covenant\u201d \u2014 using the same Hebrew verb applied to Adam's keeping of the garden in Genesis 2:15, signaling a demand for strict obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Explanation: circumcision becomes the sign of the covenant \u201cin the flesh,\u201d marking the covenant \u201cthroughout your generations\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Sanction: Genesis 17:14 \u2014 an uncircumcised male is to be \u201ccut off from his people\u201d for having \u201cbroken my covenant\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Explanation: ongoing enjoyment of the covenant's blessings depends on obedience to this positive law (not a moral law in itself, and later removed); circumcision's primary purpose is to mark the boundaries of the covenant people","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Explanation: circumcision therefore functions as both a promise of blessing and a threat of curse simultaneously \u2014 cutting the flesh pictures the threat of being cut off","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Historical note: Israel later grew prideful over circumcision, dividing the world into \u201ccircumcised\u201d and \u201cuncircumcised,\u201d while largely ignoring both the covenant's transnational purpose and its embedded threat of curse","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. Resolving an apparent tension between Genesis 15 and Genesis 17","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Problem: some contrast Genesis 15 (seemingly unilateral and guaranteed) with Genesis 17 (seemingly bilateral and conditional)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Resolution: all these elements work together as one covenant \u2014 God's promises of multiplication, land, kings, and a blessing-bringing descendant are sure, while Abraham's descendants must keep the covenant (via circumcision) or forfeit their own participation in it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Further resolution: the promises were nationally guaranteed but not individually guaranteed","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: God kept every promise at the national level \u2014 the nation multiplied, inherited Canaan, and the promised seed was born","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Proof: not every individual Israelite enjoyed the full benefits \u2014 the wilderness generation and Moses both forfeited personal participation through disobedience despite the nation's corporate fulfillment","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iv. Conclusion","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Abrahamic Covenant includes sanctioned commitments on both sides \u2014 God's and the offspring's","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. From man's side, the principle governing enjoyment of blessing is obedience to a positive command, making this (for man) functionally a covenant of works","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. God kept all His promises in full; any lack of enjoyment stemmed from Israel's own unfaithfulness, not God's","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"4. The Realization of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Scripture carefully records God's fulfillment of every element of this covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof \u2014 the land: Joshua 21:43\u201345 (all the land given, rest given, not one promise failed); Nehemiah 9:7\u20138 (God kept His promise)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Proof \u2014 the multiplied descendants: 1 Kings 4:20; Hebrews 11:12","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Proof \u2014 the promised seed: Luke 1:54\u201355 and 1:68, 72\u201375 (Mary's and Zechariah's songs)","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Conclusion: God was fully faithful to every promise made to Abraham","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"5. The Foundation of the Old Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Genesis 12\u201317 lays the foundation for the whole of redemptive history up to Christ's advent, since Israel's identity was built entirely on these promises","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Proof \u2014 Old Testament witnesses that consistently look back to Abraham's covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Isaac to Jacob (Genesis 28:4); God to Jacob (Genesis 35:12); God to Moses (Exodus 6:2\u20134); Moses to God (Exodus 32:13); Moses to the people (Deuteronomy 1:8); God to Joshua (Joshua 1:6); Psalm 105:6\u201311; Jeremiah 11:2\u20135","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. In each, the covenant is consistently summarized as a promise to give the land to Abraham's descendants","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Proof \u2014 New Testament witnesses who claim the same identity","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Paul (Romans 11:1; 2 Corinthians 11:22); Peter (Acts 3:25\u201326); Stephen (Acts 7:2\u20133, 8); the writer to the Hebrews (7:5); John the Baptist (Luke 3:8\u20139)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Later generations, however far removed, consistently look to Abraham's federal headship as the foundation of their identity","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Conclusion","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The Abrahamic Covenant is first and foremost an earthly covenant of national, earthly promises \u2014 those descending from Abraham according to the flesh inherit Canaan, and this is the foundational identity of Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Because subsequent covenants are made with the same parties, in the same realm, with the same promises, precepts, and penalties, the \u201cOld Covenant\u201d should be understood to include the Abrahamic, Mosaic, and Davidic Covenants together","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"a. The Abrahamic Covenant anticipates the Mosaic Covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: circumcision's disinheritance-for-disobedience structure anticipates the same structure in the Mosaic Covenant","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: Nehemiah Coxe describes the Abrahamic Covenant as drawing \u201cthe first Lines\u201d of the covenant-relation later fully stated in the law of Moses \u2014 \u201cDo this and live\u201d","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Explanation: the Mosaic Covenant is a large-scale expansion of what begins with Abraham in circumcision, sharing the same scope (life in Canaan) and the same people (Abraham's offspring)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Explanation: the roughly 400-year gap between the covenants explains this connection \u2014 the fuller complex of laws was unnecessary while Israel was nomadic or enslaved, and was delivered once the Exodus began","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The Abrahamic Covenant anticipates the Davidic Covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the twice-repeated promise of royalty \u2014 to Abraham and Sarah, then picked up again with Jacob and Judah \u2014 anticipates the coming Davidic Covenant","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The Abrahamic Covenant anticipates the New Covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First way: it promises the New Covenant","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Assertion: the covenant's promised blessing-bringing descendant is, in substance, the promise of the New Covenant itself, since the benefits of Christ's work come through that covenant","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Conclusion: the Abrahamic Covenant does not merely anticipate the New Covenant but carries it within itself \u2014 it promises the New Covenant by promising the New Covenant's Mediator","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second way: it typologically pictures the New Covenant","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Assertion: the Abrahamic Covenant typologically pictures something other and greater than itself","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Proof: Meredith Kline describes two distinct levels of fulfillment \u2014 provisional/prototypal and messianic/eternal \u2014 present in the king-promise given to Abraham, and argues the same applies to the promised kingdom-people and kingdom-land","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Explanation: Abraham's multiplied offspring, living in Canaan under their own rulers, function as types pointing to a greater, heavenly, antitypical fulfillment","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Explanation: from the outset, the covenant anticipates a transnational blessing reaching beyond Abraham's own descendants (Romans 4:10)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Explanation: this combination of typology and a special fleshly relation to Christ makes the Abrahamic Covenant a covenant of guardianship \u2014 its purpose is to bring the New Covenant into being by bringing its founder into being","bibleReferences":[],"subsections":[]},{"level":5,"heading":"v. Proof: no covenant prior to Christ reveals His covenant as directly as this one, since the free, unilateral gift of its earthly, typical promises models the free, unilateral gift of the New Covenant's heavenly, antitypical promises","bibleReferences":[],"subsections":[]},{"level":5,"heading":"vi. Proof: Hebrews 11:9\u201310 shows Abraham looking forward to a greater city than Canaan, and other Old Testament saints likewise understood the typology, though not completely","bibleReferences":[],"subsections":[]},{"level":5,"heading":"vii. Conclusion","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Old Testament saints are one people with New Testament believers, since the universal church began as far back as Adam and Eve and included all who believed the gospel promises as revealed through typology","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Their heavenly inheritance came not through the Abrahamic Covenant itself, but through the One it promised and pictured \u2014 meaning the Abrahamic Covenant functions as a covenant of guardianship, marking out the people and place of the Messiah's birth","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"d. The Abrahamic Covenant echoes Eden","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the foundational pattern established in Eden is picked up and expanded in the Abrahamic Covenant","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Comparison","bibleReferences":[],"subsections":[{"level":5,"heading":"i. In Eden, God set apart a special place and commissioned a particular person (Adam) to bring blessing to the world; in Abraham, God sets apart a new special place and a particular descendant to bring blessing to the world","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Israel, like Adam, is treated throughout the Old Testament as a new son of God in a new paradise with a new temple","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Conclusion: like Adam, Israel proved an unfaithful son and was cursed, disinherited, and expelled","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. In successive stages, God covenanted with Abraham to multiply his offspring and give them Canaan, to be lived in under their own rulers after a period of sojourning and slavery","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Abraham's descendants, for their part, were required to keep the covenant through circumcision, on pain of individual \u2014 not national \u2014 disinheritance","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Conclusion: from among Abraham's offspring, one descendant would bring a blessing for all the families of the earth","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":7,"title":"Chapter 7: The Mosaic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Israel had every reason to obey God out of sheer gratitude even before the Exodus","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Conclusion: their enslavement in and deliverance from Egypt gave that obedience an even deeper context","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Context of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The promise of oppression and affliction","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Genesis 15:13\u201316 had told Abraham that 400 years would pass, much of it spent in foreign servitude, before the full inheritance of Canaan","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Illustration: just as confessions of faith from the 16th\u201317th centuries already feel distant to us today, 400 years is a vast span \u2014 an Israelite slave in Egypt knew the ancestors' stories only as stories, immersed instead in slavery and Egypt's grandeur","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Context: it is in this setting that Israel cries out to a God they barely knew (Exodus 2:23\u201325)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Proof: Exodus 12:40\u201341 confirms the 430-year span","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: the appointed time had come","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The promise of liberation and fulfilment","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: alongside Israel's slavery, God's promise to bring Abraham's descendants into Canaan remained unfulfilled \u2014 deliverance was now required","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Text: Exodus 3:13\u201317 \u2014 at the burning bush, God identifies Himself as \u201cI AM\u201d and \u201cthe God of your fathers,\u201d promising deliverance from Egypt into Canaan","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Text: Exodus 6:1\u20135 \u2014 God explicitly ties the coming deliverance to His remembrance of \u201cmy covenant\u201d with Abraham","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Assertion: the context of the Mosaic Covenant is therefore the Abrahamic Covenant \u2014 God is fulfilling what He swore","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: this deliverance is God's own faithfulness to Abraham, Israel's federal head","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Description: God's redemption of Israel overpowers both the greatest human power (Egypt) and the greatest natural power (the deep), as Psalm 77:20 reflects","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Conclusion: the Exodus profoundly shaped the Israelite mind and became one of the most foundational, frequently-referenced events in the rest of the Old Testament","bibleReferences":[],"subsections":[]},{"level":4,"heading":"g. Conclusion of this section: the Mosaic Covenant develops the same covenantal relationship God initiated with Abraham, and the narrative's heavy emphasis on that connection strengthens the ongoing bond between the two covenants","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. The Kind of Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Like the Abrahamic Covenant, the Mosaic Covenant guarantees blessing nationally while conditioning individual enjoyment of it on obedience","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Its laws","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First text and assertion: Exodus 19:3\u20138 \u2014 God tells Israel that if they obey His voice and keep His covenant, they will be His treasured possession, a kingdom of priests and a holy nation; the people respond, \u201cAll that the LORD has spoken we will do\u201d","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: this covenant rests on both God's commitment to bless and the people's commitment to obey, paralleling the pattern in Genesis 17 (kindness first, then a demand for loyalty backed by the threat of disinheritance) \u2014 and it applies to the very same people, Abraham's offspring","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second text: Exodus 20 \u2014 the Ten Commandments open by repeating God's deliverance (\u201cI am the LORD your God, who brought you out of the land of Egypt\u201d)","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the demand for loyalty is grounded in what God has already done, yet Israel must remain faithful to continue enjoying the covenant's blessings","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Third text: Exodus 24:3\u20138 \u2014 the people again pledge obedience, and Moses formalizes this with sacrifices, an altar, twelve pillars, and blood sprinkled on the people","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the sprinkling of blood functions as an oath of loyalty and a vow of accountability \u2014 the placement of covenant sanctions","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof: Hebrews 9:18\u201323 shows this ritual accomplished both sanctions and sanctification, purifying the people and declaring them set apart, obligated to remain pure or suffer the consequences","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Historical note: despite this pledge, Israel proved unfaithful almost immediately (the golden calf), leading Moses to smash the first tablets before God ordered a second set made","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Fourth text: Exodus 34:27\u201328 \u2014 at the second giving of the law, God says the covenant is made \u201cin accordance with these words,\u201d identifying the Ten Commandments as \u201cthe words of the covenant\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Conclusion: the moral and positive law together form the foundation of this covenant; Israel swore obedience under oath and sanction, and enjoying the covenant's benefits depends on keeping that law","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Its promises","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the laws of the Mosaic Covenant are a major expansion of the initial command of circumcision, fitted for a people about to settle permanently in the land","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the fuller complex of social laws was unnecessary for a nomadic or enslaved people, and was delivered once the Exodus and the march toward Canaan began","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Assertion: the promises of the Mosaic Covenant are simply the further enjoyment of what God had already promised Abraham","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Example: the command to honor one's parents is directly tied to long life in the land","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof: the Exodus itself took place to fulfill the Abrahamic promise, yet enjoying that promise now also requires obedience to the Mosaic laws and statutes, not circumcision alone","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Proof text: Jeremiah 11:2\u20135 (compare 7:3\u20137) demonstrates this direct dependence","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Explanation: because the Abrahamic and Mosaic Covenants function together as two covenants governing one kingdom, corporate and individual principles intertwine","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Illustration 1: after the golden calf, many individual Israelites were killed for their infidelity, yet Moses appealed to the Abrahamic promise as the basis on which God must not destroy the nation entirely (Exodus 32:13)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Illustration 2: a whole generation died in the wilderness for disobedience, yet God kept His promises to the next generation","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: the promises of the Mosaic Covenant are nothing more or less than those of the Abrahamic Covenant \u2014 obedience to the one secures the blessings of the other","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Its threats","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: the blood sprinkled at the covenant-making ceremony sanctioned Israel's vow with the threat of death; Moses made plain that obedience brings blessing in the land and disobedience brings curse and exile","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Context: this threat is repeated as Israel nears the land after the unfaithful generation dies \u2014 Deuteronomy renews the same covenant, with the same promises and threats, for the second generation, since they remain Abraham's offspring","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Text: Deuteronomy 6:20, 24\u201325 \u2014 parents are to explain to their children that blessing follows obedience to God's statutes","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Text: Deuteronomy 11:26\u201328 \u2014 a blessing and a curse are set before Israel, contingent on obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Text: Deuteronomy 27:26 \u2014 \u201cCursed be anyone who does not confirm the words of this law by doing them,\u201d met with the people's \u201cAmen\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Notable passage: Deuteronomy 29:22\u201328 \u2014 God tells Israel in advance that they will be unfaithful, cursed, and exiled, and instructs them to explain afterward to their children that their own disobedience caused it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"g. Text: Deuteronomy 30:15\u201320 \u2014 the covenant's summary: \u201cI have set before you today life and good, death and evil\u2026 Therefore choose life\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"h. Conclusion: based on its laws, promises, and threats, the Mosaic Covenant functions as a covenant of works for life in Canaan \u2014 obedience secures the guaranteed blessings of the Abrahamic Covenant, and disobedience brings its guaranteed curses","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Kindness of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The Mosaic Covenant is a covenant of obedience for life in Canaan, but it is not identical to Adam's original Covenant of Works \u2014 it echoes and revives that covenant while differing in place, parties, promises, and positive laws","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Contrast: Adam's covenant was all-or-nothing, threatening immediate and complete condemnation for a single failure in perfect righteousness; the Mosaic Covenant, while still demanding obedience and threatening curses, contains real elements of kindness Adam's covenant lacked","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The absolute dominion of God","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God's kindness is visible when measured against His absolute dominion over Israel","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: any \u201cdo this, and I will grant that\u201d arrangement is itself gracious, since God was never obligated to offer it","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Explanation: offering blessed life in Canaan, attainable through obedience that even an unbeliever could outwardly render, is a kind gift meant to produce gratitude and diligence rather than entitlement","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Extension: this kindness is heightened further because Israel is not merely a creature but a sinner","bibleReferences":[],"subsections":[{"level":5,"heading":"i. God owes sinners no blessing and has every right to judge them fully","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Conclusion: for God to establish a covenant of blessing with fallen Israel \u2014 a people whose nature the Abrahamic Covenant had not changed \u2014 is a double kindness, in light of both His dominion and their sin","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. The promises to Abraham","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: Israel's golden-calf idolatry was an especially grave sin against grace and light, given God's recent deliverance at the Red Sea and defeat of Egypt","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Qualification: this should be contextualized \u2014 only a short time had passed since the giving of the Ten Commandments compared to the long span in Egypt, whose visible, ancient, and impressive idol-centered religion had shaped Israel for generations, making their quick unfaithfulness explainable, if not excusable","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Consequence: Israel was punished for this unfaithfulness (the Levites' killing of the offenders, the ground idol mixed into drinking water, the plague)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Text: Exodus 32:13\u201314 \u2014 Moses appeals to God's sworn promises to Abraham, Isaac, and Israel, and God relents from destroying the people","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Explanation: Moses' appeal shows that Israel's destruction would have made God's promise to Abraham impossible to fulfill \u2014 a pattern repeated throughout Israel's history, where the nation is preserved because the promise to Abraham must still be kept","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Conclusion: God's faithfulness to Abraham functions as a kind guarantee of Israel's ongoing status as a blessed nation, and Scripture records that He delivered on that promise in full","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The sacrificial system","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: since neither the Abrahamic nor the Mosaic Covenant changed Israel's sinful nature or granted a new heart, ongoing disobedience was unsurprising \u2014 but God provided the sacrificial system as a means of real, repeated forgiveness","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Note: the seemingly tedious detail of Leviticus and Numbers is essential \u2014 without these provisions, Israel would have been exiled far sooner","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Text/example: Leviticus 5:14\u201319 \u2014 guilt and sin offerings provide atonement for both unintentional and some intentional sins","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the substitute's blood pays the penalty the sinner deserved, achieving atonement and redirecting guilt to the sacrificial victim; this repeated rhythm \u2014 daily, weekly, monthly, yearly \u2014 taught Israel both its own sinfulness and God's kindness in providing atonement","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Text: Leviticus 16:21\u201322, 30\u201334 \u2014 the Day of Atonement, where the high priest represents the whole nation and its sins are visibly carried away on the scapegoat","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the priest, not the individual worshiper, accomplishes this cleansing, assuring the nation of restored purity before the law","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Conclusion: this is real kindness \u2014 God's standard of justice never relaxed, but the sacrifices accounted for Israel's sin, and the whole system functioned as a teaching tool pointing toward a heavenly sacrifice, offered by a heavenly High Priest, in a heavenly temple","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Qualification: this forgiveness, per Hebrews, was earthly and outward \u2014 \u201cpurification of the flesh\u201d rather than the conscience \u2014 carrying a positive message of atonement alongside a continued reminder of sin","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. The history of Israel","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Summary assertion: Israel's history plays out exactly as predicted \u2014 disobedience, forgiveness through right worship, fulfillment of the promises to Abraham and the rise of the kingly line, later apostasy, prophetic warnings, rejected worship, and finally exile \u2014 yet God remains gracious throughout, exactly as He said He would be","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Text: Deuteronomy 4:25\u201331 predicts Israel's future corruption and exile, but also promises that if Israel seeks the Lord, \u201che will not\u2026 forget the covenant with your fathers that he swore to them\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Explanation: God does not fully and finally disinherit Israel even in exile, because the blessing for the nations \u2014 the promised seed \u2014 had not yet been born; God preserves Israel long enough to bring that seed into the world","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Text: Nehemiah 9 \u2014 Israel's own retelling of its history after the exile: God kept His promise to Abraham (vv. 7\u20138), gave good laws at Sinai (v. 13), and though Israel disobeyed repeatedly despite many warnings, God \u201cin your great mercies did not make an end of them\u201d (vv. 29\u201333)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: Israel's own history testifies to God's kindness \u2014 He is the God who keeps covenant and steadfast love from beginning to end, and the Mosaic Covenant, though built on law and obedience, was administered with real, repeated grace through the covenant itself, the sacrificial system, and God's ongoing restoration of His people","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. The Function of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Principle: a kingdom is delegated dominion, granted through covenant \u2014 the kingdom of creation was governed by the Covenant of Works and the Noahic Covenant, and the kingdom of Israel was granted to Abraham (land, laws, promises, a line of kings)","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Conclusion: the Mosaic Covenant is a major development of the kingdom of Israel, governing it fully alongside the Abrahamic Covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The covenant governs the people","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Text: Deuteronomy 4:1\u20132 \u2014 Moses instructs Israel not to add to or subtract from the law, but to keep and obey it as their governing standard","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: Israel is governed by two basic kinds of law","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Moral law \u2014 known by nature, though suppressed, and summarized in the Ten Commandments","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive law \u2014 additional commands not inherently right or wrong in themselves (circumcision, tabernacle construction, sacrifices, dietary laws)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Often subdivided further into civil/judicial law (daily affairs and punishments) and ceremonial law (priesthood, sacrifices, cleanness)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Conclusion: together, the moral and positive law govern every dimension of the people's life in the kingdom of Israel","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The covenant governs the priesthood","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the Mosaic law regulates the priesthood directly","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: the law appoints the tribe of Levi to priestly service; Hebrews contrasts Aaron's priesthood, based on a law of bodily descent, with Jesus' priesthood, based on the Father's direct appointment","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Example 1: Exodus 40:12\u201316 \u2014 Aaron and his sons are consecrated as \u201ca perpetual priesthood,\u201d a right no other tribe could claim","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Example 2: Leviticus 10:1\u20132 \u2014 Nadab and Abihu are judged for offering \u201cstrange fire\u201d not commanded by God, showing the priesthood had no authority beyond what God had specified","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Conclusion: the Mosaic law creates, controls, and corrects the priesthood as needed","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The covenant governs the kingship","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Principle: everyone in Israel \u2014 people, priests, and kings alike \u2014 remains under God's authority; His delegated dominion never surrenders His own sovereignty","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Context: the Abrahamic Covenant promised a line of kings, and the Mosaic Covenant supplies the laws that govern them","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Text: Deuteronomy 17:14\u201320 \u2014 the king must be chosen by God from among Israel's own brothers, must not multiply horses, wives, or wealth, and must personally copy, read, and obey the law throughout his reign","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Contrast: in surrounding nations, the king creates the law and effectively is the law; in Israel, the king is created by the law and must submit to it \u2014 God alone is king, and His law controls the kingship","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. The covenant governs the prophets","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Principle: the Mosaic Covenant regulates the prophetic office just as it regulates every other part of Israel's national life","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Text: Numbers 12:6 \u2014 God's rebuke of Miriam's grumbling establishes that only those God appoints may serve as prophets","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Text: Deuteronomy 13:1\u20135 \u2014 the test of a true prophet is not merely whether a prediction comes true, but whether the prophet's words align with God's existing law","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Comparison: this echoes Adam, who was likewise charged with guarding the purity of God's word in Eden, and failed","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: prophets exist to reinforce the law and call Israel back to obedience; the law itself controls both the identity and the message of legitimate prophets, and anyone unauthorized was to be rejected and executed","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. The covenant governs blessing and cursing","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Transition: the previous points govern the people's relationships with one another; this point governs Israel's relationship with God, the great King of the kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Principle: obedience brings God's blessing; disobedience brings God's curse","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Illustration: before entering Canaan, the Levites are divided onto two hills \u2014 one pronouncing curses for disobedience, the other blessings for obedience (Deuteronomy 27:9\u201310, concluding in v. 26 with the people's \u201cAmen\u201d), mirrored by the blessings recorded in Deuteronomy 28:1\u20132","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Ongoing practice: Deuteronomy 31:9\u201313 commands the law to be read publicly every seven years at the Feast of Booths, so that the people and their children \u201cmay hear and learn to fear the LORD\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Text: Deuteronomy 32:45\u201347 \u2014 Moses' concluding summary: \u201cit is no empty word for you, but your very life\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Conclusion: obedience brings blessing and disobedience brings curse \u2014 this is the covenant's basic function of ruling the kingdom","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The Mosaic Covenant governs everything \u2014 the people through its laws, the priests, the kings, and the prophets \u2014 with blessing for obedience and curse for disobedience","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Just as God required Abraham's household to keep the covenant or be cut off, the Mosaic Covenant expands that same relationship, controlling the ongoing enjoyment of the very same Abrahamic blessings","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. The Abrahamic Covenant established the kingdom of Israel and its basic obligations; the Mosaic Covenant expanded and implemented its government as the kingdom took shape in Canaan","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Forward-looking conclusion: the Mosaic Covenant also significantly advances the mystery of Christ, especially through its priesthood and sacrifices \u2014 as Hebrews 10:1 states, the law is \u201cbut a shadow of the good things to come,\u201d and that shadowy status was itself its great privilege, beginning to sketch the outline of the Savior later focused fully in the Davidic Covenant","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":8,"title":"Chapter 8: The Davidic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. With Israel now settled in the land under the Mosaic law, God's covenant with David brings the kingdom of Israel to its full, mature form","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Context of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Several converging threads set the stage for God's covenant with David","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The promises of the Abrahamic Covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God had already promised Abraham that kings would descend from him, a promise later narrowed to the tribe of Judah","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Conclusion: a covenant establishing kingship is therefore a direct outworking of that earlier Abrahamic promise, not something new or unrelated to it","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The problems of the Mosaic Covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: once Israel settled in Canaan, a new generation arose that did not know what it had cost to get there","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Consequence: this generation fell into disobedience and idolatry","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Illustration: the chaos of the Judges period is summarized by its own repeated refrain \u2014 everyone did what was right in his own eyes, because there was no king in Israel","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: Judges depicts a repeating cycle of disobedience, oppression, and only partial deliverance, marked by no centrality, no leadership, and no cohesion for the nation","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: this chaos showed the nation's desperate need for someone to keep God's law on the people's behalf \u2014 someone who could secure blessing and deliverance for all of Abraham's children","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The preference of the people","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Israel's demand for a king \u201clike the other nations\u201d (1 Samuel 8) was itself a rejection of God's own kingship","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: God tells Samuel that Israel has \u201cnot rejected you, but they have rejected me from being king over them\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Explanation: Israel wanted a king who would judge them by new laws of his own making, rather than one who would lead them under God's existing law","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Application: Saul, Israel's first king, was chosen according to this flawed desire rather than God's own selection","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Contrast","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: David was directly chosen and covenanted with by God Himself","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: Saul's kingship was not established according to God's choosing, but was set up by human preference","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Conclusion: because it rested on human initiative rather than divine appointment, Saul's kingship ultimately fell apart","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. The prospect of consummation","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the law of Moses had already anticipated a future time of rest, when God would establish one central place for His presence and worship","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Conclusion: this expectation set up exactly what David's covenant would go on to fulfill","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. The Blessings of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Context: God's covenant with David, recorded in 2 Samuel 7, promises three main things","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. An established throne","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Text: 2 Samuel 7:16 \u2014 \u201cyour throne shall be established forever\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: David's dynasty is secured by God's own sworn commitment","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it is not a kingship built merely on the people's own initiative, as Saul's had been","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: this gives the nation lasting stability, centered on a king of God's own choosing","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Rest and prosperity in Canaan","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the covenant promises Israel security and peace in the land","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: this promise of rest was only partially realized earlier under Joshua","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Proof/Fulfillment: 1 Kings 8:56 \u2014 Solomon declares that \u201cthe LORD\u2026 has given rest to his people Israel, according to all that he promised\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Conclusion: the promise of rest reaches its fuller completion under David and Solomon","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The presence and protection of God","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: central to the covenant is the promise that God's own presence would dwell among His people","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Fulfillment: this promise is ultimately realized through the building of the temple under Solomon","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Climactic conclusion: Solomon's dedication of the temple marks the high point of the entire Old Testament, where the promises made to Abraham, to Moses, and to David all reach their zenith together","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Conditions of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Alongside its promises, the covenant places real obligations on David's line","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Guard God's sanctuary","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the king bears responsibility for building and protecting the purity of God's temple and worship","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Conclusion: this gives Israelite kingship a priestly dimension","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Keep God's law","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the king is required to know, copy, and personally obey God's law, per the pattern already set in Deuteronomy 17","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: the king submits to and upholds the existing law","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: the king does not create his own law, unlike the kings of other nations","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: this gives the kingship a prophetic dimension as well","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Represent God's people","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Contrast: unlike Moses, who mediated the law but was never himself a federal head whose descent determined others' standing, the Davidic king functions as a true federal head for the nation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: the Davidic Covenant established David's heirs as the representatives, or federal heads, of the kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Consequence: the king's own faithfulness or unfaithfulness directly determines the blessing or cursing of the whole people \u2014 as goes the king, so goes the kingdom","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. The Sanctions of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Like every covenant, this one is guaranteed and enforced by real consequences","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The judgment of God himself","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God promises to discipline unfaithful sons of David directly","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Description: this relationship is described in terms of a father and a son","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Expulsion from the land of Canaan","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: persistent unfaithfulness in the king ultimately brings the same covenant curse threatened back in Moses' day \u2014 national exile from the land","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Exegetical/historical steps","bibleReferences":[],"subsections":[{"level":5,"heading":"i. First text: 1 Kings 9:4\u20139 \u2014 God tells Solomon that continued obedience secures the throne, while turning to other gods will get Israel \u201ccut off\u2026 from the land\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Second text: 1 Kings 11:11\u201313 \u2014 God fulfills that very threat, tearing most of the kingdom away from Solomon's son","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Qualification: yet for the sake of David, God preserves one tribe rather than removing everything at once","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. Comparison: this mirrors the Abrahamic Covenant's own pattern \u2014 the promise to the line as a whole is sure, while individual, unfaithful members of that line can still be cut off from its blessings","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Historical realization: this pattern of expulsion plays out historically, first partially in Solomon's later years, and finally in full in the exiles of both Israel and Judah","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Together, the Abrahamic, Mosaic, and Davidic Covenants form one unified structure governing the kingdom of Israel","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. The king's obedience to Moses' law determines whether the nation enjoys or forfeits the blessings originally promised to Abraham","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":9,"title":"Chapter 9: The Messiah of the Old Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Tracing how the concept of the Messiah developed within Israel's kingdom and covenants is really tracing the unfolding of the mystery of Christ itself","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Basis: \u201cMessiah\u201d and \u201cChrist\u201d are simply the same title in two languages","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Messianic Purpose of the Old Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: from Genesis 12 onward, Israel's covenants existed to produce the one promised descendant who would bless the nations","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Two levels of this typological purpose","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Broadly: the entire kingdom of Israel and its covenants were themselves typical","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Canaan, the sacrifices, the priesthood, David's victories, and the exodus all functioned as shadows of greater heavenly realities","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Proof: Hebrews 10:1","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Narrowly: the ongoing progress of the covenants increasingly focused Israel's expectation on one particular person","bibleReferences":[],"subsections":[{"level":5,"heading":"1. This sharpens the broad, general typological picture into hope for a specific individual \u2014 the son of David, the Messiah","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. The Messianic Hope of the Old Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Israel's hope in \u201cthe anointed one\u201d developed over time as historical circumstances shifted","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The present Messiah","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Israel's messianic hope originally centered on the reigning Davidic king himself","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Basis: by virtue of the Davidic Covenant, the king himself was, quite literally, God's \u201canointed one\u201d \u2014 \u201cthe king is messiah\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Proof","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Psalm 18:50 \u2014 God \u201cshows steadfast love to his anointed, to David and his offspring forever\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Psalm 20:6\u20139 \u2014 the people declare that \u201cthe LORD saves his anointed,\u201d trusting not in chariots and horses but in the anointed king himself","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: the messianic concept therefore originated as confidence in the present, currently reigning Davidic king in Jerusalem","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The future Messiah","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Context: one king after another failed to live up to the covenant's demands","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Illustration: Psalm 89","bibleReferences":[],"subsections":[{"level":5,"heading":"i. First movement: the psalm rehearses God's unconditional promise that David's throne would be \u201cestablished forever\u201d (vv. 28\u201337)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Second movement: the psalm then abruptly laments Israel's actual experience of defeat and exile \u2014 \u201cyou have renounced the covenant with your servant\u2026 cast his throne to the ground\u201d (vv. 39, 44)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Problem/Resolution: this collision between the sworn promise and Israel's lived failure is what caused hope to shift from the present to the future","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: with each flawed ruler, Israel looked ahead to the next one, awaiting a truly righteous king whose throne would finally be established as promised \u2014 especially sharpened by the experience of exile","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Messianic Promise of a New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Context: in the depths of exile, the prophets began revealing that the coming Messiah would not merely restore the nation to its former state","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Assertion: instead, he would bring an entirely new kind of covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Exegetical text: Jeremiah 31:31\u201334","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: this New Covenant is explicitly \u201cnot like the covenant that I made with their fathers\u2026 my covenant that they broke\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: instead of external law paired with repeated failure, it promises internal transformation \u2014 \u201cI will put my law within them, and I will write it on their hearts\u201d","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Further promise: complete, permanent forgiveness \u2014 \u201cI will remember their sin no more\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Comparison: unlike the old sacrifices, which provided only outward \u201cpurification of the flesh,\u201d this covenant forgives sins outright","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Conclusion: the New Covenant is categorically different from the Mosaic Covenant, not simply an improved version of the same arrangement","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"4. The Messianic Inclusion of the Nations","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: the prophets also made clear that the coming Messiah's blessings would extend beyond Israel alone","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Explanation: this expected fulfillment would gather people from every nation into a renewed and perfected place of worship","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Conclusion: the New Covenant's scope was never intended to remain confined to ethnic Israel, but to draw in the nations as originally promised to Abraham","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"5. The Typological Nature of the Kingdom","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: all of this Messianic hope was revealed through typology rather than plain, direct statement","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Explanation: because present realities pointed to future realities greater and other than themselves, Israel's own messianic expectations tended to stay tied to an idealized version of their present national existence","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Victory over foreign powers","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. A rebuilt temple","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. The nations becoming Jewish, rather than Jew and Gentile united in something new","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Consequence: this caused Israel to underestimate just how different, and how much better, the promised New Covenant would actually be","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Conclusion: Israel failed to realize how unlike the Old Covenant the New Covenant would be, and why that unlikeness was itself such a blessed reality","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Across the whole sweep from Abraham to David, God's unfolding revelation pointed toward a coming son of David","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. This coming son would unite Israel and the nations through a new covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Fulfillment: this hope was finally realized in the arrival of Jesus","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":10,"title":"Chapter 10: The Ministry of Christ","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Israel expected the Messiah to perfect their present national existence and free them from foreign rule","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Contrast","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Positive: Jesus' actual ministry unveiled something genuinely new","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Negative: it did not deliver the political restoration Israel was expecting","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion: this gap is precisely why many Jews found His ministry confusing and offensive","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Gospel of the Kingdom","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: from the start of His ministry, Jesus preached good news calling for repentance and faith","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Explanation: this good news went beyond the immediate healings and exorcisms He performed","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. The actual content of the good news","bibleReferences":[],"subsections":[{"level":4,"heading":"i. That He was going to offer Himself up as a sacrifice","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. That He would rise from the dead","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. That He would grant eternal life to all who trusted in Him","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Proof/Illustration: His words to Martha \u2014 \u201cI am the resurrection and the life\u2026 Do you believe this?\u201d","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Conclusion: the gospel of the kingdom centered not on physical restoration but on His coming death, resurrection, and the gift of eternal life","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"2. The Kingdom of Heaven","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Jesus described a kingdom that is fundamentally not of this world","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Evidence of this \u201cnot of this world\u201d character","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Entrance by spiritual rebirth, not physical descent","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: John 3:3\u20136 \u2014 the kingdom is \u201cfrom above,\u201d entered by supernatural rather than natural birth","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Membership by faith, not bloodline","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: John 8:39, 56 \u2014 true sons of Abraham are those who share his belief, not merely those born of his body","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Openness to the humble","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: Matthew 18:1\u20134 \u2014 the kingdom belongs to those who become \u201clike children\u201d","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Consequence \u2014 why this provoked the religious leaders","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Jesus taught that Abraham's physical offspring were merely tenant workers with no automatic claim on the kingdom apart from faith in Him","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: a Gentile could inherit the kingdom by faith","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: an unbelieving Jew, despite his ancestry, could be excluded from it","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Conclusion: this deeply provoked leaders who assumed automatic inclusion by virtue of their Jewish ancestry","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"3. The King of the Kingdom","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Jesus claimed the full threefold office of prophet, priest, and king over this kingdom","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. The threefold office","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Prophet: He stood in the seat of Moses, interpreting, applying, and personifying the law","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Priest: He brings the people near to God through sacrifice","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. King: He claimed absolute authority in the kingdom of heaven, establishing it as a kingdom of righteousness","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Illustration: the crowd's use of Psalm 118 in Matthew 21:9","bibleReferences":[],"subsections":[{"level":4,"heading":"i. True expectation: the crowd rightly hailed Jesus as \u201cthe Son of David,\u201d using genuinely messianic language","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Mistaken expectation: they expected Him to vanquish Roman rule","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Contrast \u2014 what He actually came to do","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: He came to destroy Satan, mankind's ancient foe, and to be not merely the king of Psalm 118 but its festal sacrifice","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: He had not come to overthrow Rome","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iv. Fulfillment: the very night He was betrayed, He laid down His life and announced a new covenant of forgiveness in His own blood","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Jesus' earthly ministry began unveiling God's complete redemptive plan","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. This plan gathers a new humanity into a new kingdom through a new covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. This kingdom is received simply by faith in Him","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":11,"title":"Chapter 11: The Covenant of Redemption","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: before time began, salvation in Christ was already planned","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Explanation: Scripture presents this eternal plan in covenantal terms, as a transaction among the persons of the Trinity","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Parties of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: the Father, Son, and Holy Spirit are all shown participating in this covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Proof \u2014 Isaiah's Servant Songs","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Isaiah 42:1\u20137 \u2014 the Father gives the Servant \u201cas a covenant for the people\u201d and puts His Spirit upon Him","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Isaiah 50:4\u20139 \u2014 the Servant declares His own readiness to undertake the mission","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Confirmation: Luke 4:17\u201321 \u2014 Jesus applies this Servant role directly to Himself","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Conclusion: together these texts reveal an intra-trinitarian dialogue between the Father, the Son, and the Holy Spirit concerning the redemption of an elect people","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"2. The Commitments of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Each divine person makes specific commitments within this covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. The Son's commitments","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the Father assigns the Son a threefold task","bibleReferences":[],"subsections":[{"level":5,"heading":"i. To become incarnate","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. To obey the law perfectly","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. To offer Himself up as a substitutionary sacrifice for a particular, elect people","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Appointment to a threefold office","bibleReferences":[],"subsections":[{"level":5,"heading":"i. King: Psalm 2:6\u20139 \u2014 \u201cI have set my King on Zion\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Priest: Psalm 110:4 \u2014 \u201cYou are a priest forever after the order of Melchizedek\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Prophet: Isaiah 61:1\u20132 \u2014 \u201cThe Spirit of the Lord GOD is upon me\u2026 to bring good news to the poor\u201d","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Confirmation: John 17:8 \u2014 Jesus affirms this commission Himself, \u201cI have given them the words that you gave me\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Conclusion: the Son's commitments in this covenant directly ground His threefold office as prophet, priest, and king","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The Father's commitments","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Comparison/Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: the Davidic king received the Spirit's help only conditionally, with no absolute guarantee","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: in the Covenant of Redemption, the Father engages Himself unconditionally to secure the success and completion of the Son's mission","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Means \u2014 the Holy Spirit's role","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Spirit empowered the incarnation (Luke 1:35)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The Spirit empowered the miracles (Matthew 12:27\u201328)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. The Spirit empowered the message (John 3)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. The Spirit empowered the sacrifice itself (Hebrews 9:14 \u2014 offered \u201cthrough the Eternal Spirit\u201d)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. The promised reward","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: Isaiah 53:10\u201312 \u2014 the Servant \u201cshall see his offspring\u2026 prolong his days\u2026 and I will divide him a portion with the many\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof: Philippians 2:8\u201311 \u2014 because He \u201chumbled himself by becoming obedient to the point of death\u2026 God has highly exalted him and bestowed on him the name that is above every name\u201d","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: the Father promised the Son resurrection and exaltation as the reward for faithful obedience, fulfilled when the Son \u201csat down at the right hand of God\u201d \u2014 an act of exaltation and glory proving He received the reward in full","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Fulfillment of the Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Jesus willingly carried out this mission to completion, fulfilling it on three distinct levels","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. The three levels of obedience","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The law of nature: perfectly obeying the moral law and resisting Satan's temptation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. The law of Moses: being born as a son of Abraham under the Mosaic law, never needing to offer sacrifice for His own sin","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. The law of His own covenant: giving up His life as a ransom","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Why this threefold obedience matters","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: everywhere else in the Old Testament, obedience is marked by failure or only partial fulfillment","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: the Old Testament therefore teaches Israel to expect One who is not like that","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Conclusion: Christ's perfect, threefold success is the antitype that gives the whole typological Old Covenant its meaning","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Reward: He was rewarded with resurrection and exaltation exactly as promised","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The Covenant of Redemption is the hidden foundation beneath the gospel","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Summary","bibleReferences":[],"subsections":[{"level":4,"heading":"i. What the Father planned and commissioned, the Son perfectly accomplished","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. This secures eternal salvation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. The Spirit now applies that salvation to God's people through the New Covenant","bibleReferences":[],"subsections":[]}]}]}]},{"chapterNumber":12,"title":"Chapter 12: The New Covenant of Grace","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Jesus, the promised son of Abraham, David, and God, completed His heavenly mission within Israel\u2019s earthly covenants","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Conclusion: He now freely offers everyone who believes the salvation He secured","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Establishment of the New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: Christ\u2019s death legally establishes this covenant on better promises than the old","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Comparison/Contrast","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Old Covenant sacrifices","bibleReferences":[],"subsections":[{"level":5,"heading":"1. \u201cSanctify for the purification of the flesh,\u201d reconciling worshippers to the law of Moses so they could remain in Canaan","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: they cannot perfect the conscience of the worshiper, leaving only \u201ca reminder of sins every year\u201d (Hebrews 10:3)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Christ\u2019s blood","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: Hebrews 9:14 \u2014 \u201cthe blood of Christ, who through the eternal Spirit offered himself without blemish to God\u201d purifies the conscience \u201cfrom dead works to serve the living God\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: this grants forgiveness in the court of heaven, not merely the court of Canaan","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Conclusion: Christ\u2019s blood accomplishes complete, permanent cleansing rather than the repeated, incomplete cleansing provided by animal sacrifice","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"2. The Blessings of the New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Jeremiah\u2019s promised New Covenant delivers a full range of blessings, all flowing from union with Christ","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Justification","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Definition: the legal wiping away of sins together with the imputation of Christ\u2019s own righteousness","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Proof: Romans 5:19 \u2014 \u201cas by the one man\u2019s obedience the many will be made righteous\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Explanation: this reverses Adam\u2019s condemnation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Means: received freely through faith","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Regeneration and Sanctification","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Comparison/Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: the Old Covenant could only command and condemn from the outside, offering no help toward obedience","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: the New Covenant produces genuine inward transformation","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Definition \u2014 regeneration: the birth of a child of God, an initial deposit of glory and holiness","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Definition \u2014 sanctification: the ongoing putting to death of remaining sin that flows out of that new birth","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Basis: God Himself writes His law on His people\u2019s hearts and empowers their obedience by His Spirit","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Qualification: the Old Covenant offered typical, external forgiveness, but did not grant the new birth or the indwelling of the Holy Spirit","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Adoption and Preservation","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: those regenerated become God\u2019s actual children, receiving the Spirit of adoption","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: God\u2019s fatherly discipline of His people functions to preserve and mature them","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Contrast","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: discipline here works toward the believer\u2019s good","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it does not function to condemn them","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Resurrection and Glorification","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Basis: because Christ fulfilled His own mission and was raised","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Conclusion: His people are guaranteed a future bodily resurrection and full share in His glory in the new creation","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Foundation of the New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Exegetical/theological argument: Renihan argues the New Covenant is best understood as an already-completed covenant of works, now freely mediated to God\u2019s people","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Premise: the Covenant of Redemption was itself a covenant of works between the Father and the Son","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Premise: Jesus willingly and perfectly fulfilled that covenant of works","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Conclusion: the New Covenant is therefore the fulfilled Covenant of Redemption, mediated to those for whom the Son was appointed federal head","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Clarification","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Negative: believers do not perform these works themselves","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Positive: believers receive, by faith, the eternal resurrected new-creation life that Jesus obtained by keeping the Covenant of Redemption, offered to the world in Christ by the Father","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. The Kingdom of the New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: just as the Father covenanted a kingdom to the Son in the Covenant of Redemption, that same kingdom is now covenanted to believers through the New Covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Exegetical text: Luke 22:29","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Translation argument: the Greek verb \u03b4\u03b9\u03b1\u03c4\u03af\u03b8\u03b5\u03bc\u03b1\u03b9 is the verb form of \u03b4\u03b9\u03b1\u03b8\u03ae\u03ba\u03b7 (\u201ccovenant\u201d)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Resulting translation: \u201cI covenant unto you, as my Father covenanted unto me, a kingdom\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Significance","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Son\u2019s reward in the Covenant of Redemption was not simply salvation for His people, but also a new realm \u2014 a consummated reality","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. This kingdom was covenanted to Christ by the Father, and He in turn mediates it through covenant to His own people","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Conclusion: this makes the Lord\u2019s Supper a celebration of entrance into that coming kingdom, rather than merely a memorial of Israel\u2019s exodus from Egypt","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"5. The People of the New Covenant","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: membership in the New Covenant is defined entirely by union with Christ, its federal head","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Contrast","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Positive: those united to Him by the Spirit share fully in His inheritance","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Negative: those without His Spirit have no claim to it","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The New Covenant of grace is founded in the Covenant of Redemption and sealed in Christ\u2019s blood","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. It reverses the corruption of Adam\u2019s fall","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. It grants eternal, glorious communion with God to all who belong to Christ","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":13,"title":"Chapter 13: The Mystery of Christ","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Context: the apostles were initially confused about whether Christ's kingdom would remain a Jewish national kingdom","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Resolution: Pentecost brought fuller understanding of what Jesus had been teaching all along","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Conclusion: the gospel's spread from Jerusalem outward answered lingering questions about Israel's relationship to the church by appealing to the mystery of Christ","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. The Unity of God's Plan","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: God has only ever had a single redemptive plan \u2014 to bless the whole world through the Jewish Messiah","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Proof","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Ephesians 1:9\u201310 \u2014 God's \u201cwill,\u201d \u201cpurpose,\u201d and \u201cplan\u201d is \u201cto unite all things in him\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Colossians 1:25\u201328 \u2014 Paul is commissioned \u201cto make the word of God fully known, the mystery hidden for ages and generations but now revealed\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. 1 Peter 1:10\u201312 \u2014 the prophets \u201csearched and inquired carefully\u201d into the salvation and glories they predicted, without full understanding, serving not themselves but later believers","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Contrast","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Positive: this one plan was fully unveiled through Christ and the apostles","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Negative: it was understood only partially by the Old Testament prophets themselves","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Conclusion: together these texts reveal one singular plan, a united eternal purpose revealed initially as a mystery and unveiled fully by Christ and His apostles","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"2. Israel, Christ, and the Church","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Israel's national existence, Christ's incarnation, and the church's formation are all connected as one continuous, unfolding movement rather than separate or competing plans","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Israel","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: as Abraham's natural offspring, Israel bore the unique privilege of receiving the covenants of promise","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Purpose: the ultimate purpose of those covenants was to bring forth the Messiah","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Exegetical argument: Romans 4:9\u201317","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Premise: Genesis records Abraham's faith and justification (Genesis 15) prior to his circumcision (Genesis 17)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Explanation: Paul argues this sequence was deliberately designed to make Abraham \u201cthe father of all who believe without being circumcised,\u201d as well as \u201cthe father of the circumcised\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Conclusion: free righteousness for all who believe was the telos \u2014 the destination, not the detour \u2014 of the Israelite kingdom and covenants (Romans 10:4)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Illustration: Israel functioned like \u201cthe temporary tenants and construction workers\u201d of the Messiah's kingdom","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Comparison: like a construction site's \u201cComing Soon\u201d sign and concept art","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Israel's land, temple, genealogy, and sacrifices were a picture of the Messiah and His kingdom","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Qualification","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: this picture was valuable and necessary","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: it was not itself the completed building","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"e. Conclusion: genuine \u201cJewish\u201d identity was always meant to culminate in faith in the Messiah, not in ancestry or law-keeping alone","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The Christ","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Jesus, born from Israel according to the flesh, fulfilled Israel's covenants","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Explanation: He offered His own people the first opportunity to join His kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Proof: God's preservation of a believing remnant proves He never abandoned His promises to Israel","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The Church","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: the church is the direct successor of Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Illustration/Proof \u2014 the rejected cornerstone","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Psalm 118:22\u201323 \u2014 \u201cthe stone that the builders rejected has become the cornerstone\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Ephesians 2:19\u201322 and 1 Peter 2:4\u201310 both apply this text to Christ and His church","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Explanation: though this cornerstone was first unveiled in Israel to Abraham's fleshly children, many Israelites rejected it","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Conclusion: those who believe, Jew and Gentile alike, are built into \u201ca holy temple in the Lord,\u201d making the church the antitype of Israel, and therefore its successor \u2014 the final typological fulfillment of what Israel pictured","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Assertion: the church, in an inward sense, actually predates its outward founding at Pentecost","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Explanation: the church began outwardly after Christ's death, especially at Pentecost, but its people inwardly began long before","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Basis: the conscience-cleansing benefits of the New Covenant in Christ's blood were experienced and enjoyed by many believers well before Christ's earthly ministry (Hebrews 9:25\u201326)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Illustration \u2014 David","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Psalm 51 \u2014 David appeals to God's mercy for cleansing, since animal sacrifice alone was insufficient","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Psalm 32:1 \u2014 David rejoices in the forgiveness of sins","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Confirmation: Paul quotes these very words in Romans 4:7\u20138 as the joy of one who was justified by faith","bibleReferences":[],"subsections":[]}]}]}]}]},{"level":2,"heading":"3. The Continuity of the Law and the Gospel","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: salvation by faith runs continuously through every stage of redemptive history","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Assertion: the abiding moral law likewise runs continuously through every stage of redemptive history","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Conclusion: these two continuities unite believers before and after Christ under the same gospel and the same law, now written on the heart","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The mystery of Christ is God's single eternal plan uniting Jew and Gentile in one Messiah","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Closing note: this truth is so vast that studying it should lead to worship rather than mere academic mastery","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":14,"title":"Chapter 14: The Eschatological Nature of the Kingdom","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"1. The Kingdom Inaugurated","bibleReferences":["Romans 10:14\u201315","2 Corinthians 5:20","Revelation 2:5","Romans 8:9","John 3:3"],"subsections":[]},{"level":2,"heading":"2. The Keys of the Kingdom","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Joining the kingdom through the covenant","bibleReferences":["1 Peter 4:3","Romans 10:9","Hebrews 9:15"],"subsections":[]},{"level":2,"heading":"b. Guarding the kingdom through the covenant","bibleReferences":["1 John 1:10","Hebrews 12:14","John 3:18"],"subsections":[]},{"level":2,"heading":"c. Traitors of the kingdom","bibleReferences":["1 John 2:19","Acts 8:13","2 Peter 2:1","Hebrews 6:4\u20136","Psalm 50:16"],"subsections":[]},{"level":2,"heading":"3. The Sacraments of the Kingdom","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Baptism","bibleReferences":["Romans 6:3\u20135","1 Peter 3:21\u201322","1 Corinthians 5:11"],"subsections":[]},{"level":2,"heading":"b. The Lord's Supper","bibleReferences":["Hebrews 10:23\u201325"],"subsections":[]},{"level":2,"heading":"4. The Kingdom Consummated","bibleReferences":["Acts 17:31","Acts 17:30","Psalm 2:12","2 Peter 3:15","2 Thessalonians 1:4\u201310","Hebrews 9:27\u201328","Matthew 25:31\u201346","Revelation 20:15","1 Corinthians 15:24","Revelation 21:1\u20137","Revelation 21:12","Revelation 21:26","Revelation 22:2","Revelation 21:23","Revelation 5:9\u201310","Revelation 21:3\u20134","Revelation 22:4","Revelation 22:16\u201318"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":["Romans 9:5"],"subsections":[]}]},{"chapterNumber":15,"title":"Conclusion","sections":[{"level":1,"heading":"Conclusion","bibleReferences":["Romans 8:32","Hebrews 6:19","Romans 10:11\u201313","Ephesians 3:14\u201321"],"subsections":[]}]}]}

